pragma solidity ^0.8.20;

import "../v1/FiatTokenV1.sol";
import "../v1/IERC20.sol";

/// FiatTokenV2_1 adds rescueERC20 — the live USDC admin surface. Fixture only.
contract FiatTokenV2_1 is FiatTokenV1 {
    address public rescuer;

    function rescueERC20(IERC20 token, address to, uint256 amount) external {
        require(msg.sender == rescuer);
        token.transfer(to, amount);
    }

    function updateRescuer(address newRescuer) external {
        rescuer = newRescuer;
    }
}

